def card(title,body,idx):
 im=Image.new('RGB',(1440,900),'#F5F6FA'); d=ImageDraw.Draw(im);d.rectangle((0,0,1440,200),fill='#241747');d.text((90,55),'RESCUE REPORTS',font=ImageFont.truetype(bold,24),fill='#C8AFFB');d.text((90,106),title,font=ImageFont.truetype(bold,42),fill='white')
 lines={1:['WEB  React / TypeScript / Vite','MOBILE  Flutter / Provider','API  Express / authenticated mutations','DATA  Firebase Auth / Firestore / scoped listeners','INTEGRATIONS  Cloudinary / FCM (delivery gates remain)'],9:['users → identity, role, team and active state','reports → reporter, location, status and assigned team','updates → acknowledgement and progress history','notifications / auditLogs → recipient and operational trail','server ledgers → retry identities, photos and recovery'],10:['Stable retry identities, one per unresolved payload','Profile synchronization before protected views resume','Session guards reject stale async callbacks','Bounded history reads and explicit older-entry controls','Crash recovery tests are separate from provider evidence'],12:['Source + schema + security rules + indexes','PowerPoint user guide + PDF','Narrated technical walkthrough + captions','Local Android test APK + computer demo instructions','Member names and contributions: confirm marked entries']}.get(idx,[])
 y=275
 for line in lines:d.text((95,y),line,font=ImageFont.truetype(font,29),fill='#241747');y+=88
 p=out/f'card-{idx:02}.png';im.save(p);return p
concat=[]; captions=[];offset=0;script=[]
for idx,(title,img,clip,narration) in enumerate(scenes):
 name=f'scene-{idx:02}';txt=out/f'{name}.txt';txt.write_text(narration);aif=out/f'{name}.aiff'
 subprocess.run(['say','-v','Samantha','-r','155','-f',str(txt),'-o',str(aif)],check=True)
 dur=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',str(aif)]))+1.0
 img=img if img and img.exists() else card(title,narration,idx)
 inputs=['-loop','1','-i',str(img)]
 if clip:
  v=result['clips'][clip];vd=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',v]));inputs=['-stream_loop','-1','-ss',str(max(0,vd-min(dur,35))),'-i',v]
 label=out/f'{name}-label.txt';label.write_text('SYNTHETIC NARRATION  |  FICTIONAL LOCAL DATA  |  '+title)
 video=out/f'{name}.mp4'
 banner=Image.new('RGB',(1440,90),'#241747');bd=ImageDraw.Draw(banner);bd.text((30,29),label.read_text(),font=ImageFont.truetype(font,18),fill='white');banner_path=out/f'{name}-banner.png';banner.save(banner_path)
 vf="[0:v]scale=1440:810:force_original_aspect_ratio=decrease,pad=1440:900:(ow-iw)/2:(810-ih)/2:color=0xF5F6FA[base];[base][2:v]overlay=0:810[v]"
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y',*inputs,'-i',str(aif),'-loop','1','-i',str(banner_path),'-filter_complex',vf,'-map','[v]','-map','1:a','-t',str(dur),'-r','25','-c:v','libx264','-preset','veryfast','-crf','23','-pix_fmt','yuv420p','-c:a','aac','-b:a','128k','-af','apad',str(video)],check=True)
 concat.append(f"file '{video}'")
 words=narration.split();chunks=[' '.join(words[k:k+16]) for k in range(0,len(words),16)];span=(dur-1)/len(chunks)
 for k,text in enumerate(chunks):captions.append((offset+k*span,offset+(k+1)*span,text))
 script.append(f'## {offset/60:.2f} min · {title}\n\n{narration}\n');offset+=dur
 print(name,round(dur,1),flush=True)
